def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split off pre-release (everything after '-')
        if '-' in v_no_build:
            parts = v_no_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_no_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(map(int, version_part.split('.')))

        # Parse pre-release identifiers
        if prerelease_part is not None:
            prerelease_ids = prerelease_part.split('.')
            # Convert each identifier to a tuple for comparison
            # (is_numeric, numeric_value_or_string)
            prerelease_tuples = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    prerelease_tuples.append((0, int(identifier)))
                else:
                    prerelease_tuples.append((1, identifier))
            prerelease_key = (0, tuple(prerelease_tuples))  # 0 means has prerelease
        else:
            prerelease_key = (1,)  # 1 means no prerelease (sorts after)

        return (version_nums, prerelease_key)

    # Create list of (original_index, version_string, sort_key)
    indexed_versions = []
    for i, v in enumerate(versions):
        key = parse_version(v)
        indexed_versions.append((i, v, key))

    # Sort by key, then by original index for stability
    indexed_versions.sort(key=lambda x: (x[2], x[0]))

    # Return sorted version strings
    return [v for _, v, _ in indexed_versions]

